import org.eclipse.swt.widgets.MenuItem;
import java.util.ArrayList;

class PreferenceTreeNode<T> {
    ArrayList<PreferenceTreeNode<?>> children = new ArrayList<>();
    public ArrayList<PreferenceTreeNode<?>> getChildren() { return children; }
}

class ScrolledPageContent {
    public void setRedraw(boolean redraw) {}
    public void setReflow(boolean reflow) {}
}

public class FilteredPreferenceTree {
    private ScrolledPageContent fScrolledPageContent = new ScrolledPageContent();
    private PreferenceTreeNode<?> fRoot = new PreferenceTreeNode<>();

    protected void setAllExpanded(PreferenceTreeNode<?> start, boolean expanded) {
        fScrolledPageContent.setRedraw(false);
        fScrolledPageContent.setReflow(false);
        ArrayList<PreferenceTreeNode<?>> bfsNodes= new ArrayList<>();
        if (start != null) {
            bfsNodes.add(start);
        } else {
            bfsNodes.addAll(fRoot.getChildren());
        }
        for (int i= 0; i < bfsNodes.size(); i++) {
            PreferenceTreeNode<?> node= bfsNodes.get(i);
            bfsNodes.addAll(bfsNodes.get(i).getChildren());
        }
    }

    public void someMethod(MenuItem item, boolean expand) {
        item.addSelectionListener(new SelectionAdapter() {
            @Override
            public void widgetSelected(SelectionEvent e) {
                // The rule will transform 'setAllExpanded(expand)' to this
                setAllExpanded(null, expand);
            }
        });
    }
}

